class Solution:
    def maxScore(self, edges):
        import sys
        sys.setrecursionlimit(300000)
        n = len(edges)
        ch = [[] for _ in range(n)]
        for i in range(1, n):
            ch[edges[i][0]].append((i, edges[i][1]))
        def dfs(v):
            s0 = s1 = 0
            for c, w in ch[v]:
                a, b = dfs(c)
                s1 += a
                s0 += max(a, b + w)
            return s0, s1
        return dfs(0)[0]

