class Solution {
public:
    vector<vector<pair<int,long long>>> ch;
    pair<long long,long long> dfs(int v){
        long long s0=0,s1=0;
        for(auto& [c,w]:ch[v]){
            auto r=dfs(c);
            s1+=r.first;
            s0+=max(r.first,r.second+w);
        }
        return {s0,s1};
    }
    long long maxScore(vector<vector<int>>& edges){
        int n=edges.size();
        ch.assign(n,{});
        for(int i=1;i<n;i++) ch[edges[i][0]].push_back({i,edges[i][1]});
        return dfs(0).first;
    }
};

