class Solution {
    List<List<long[]>> ch;
    long[][] memo;
    long[] dfs(int v){
        if(memo[v][2]==1) return memo[v];
        long s0=0,s1=0;
        for(long[] e: ch.get(v)){
            long[] r=dfs((int)e[0]);
            s1+=r[1];
            s0+=Math.max(r[1], r[0]+e[1]);
        }
        memo[v][0]=s0; memo[v][1]=s1; memo[v][2]=1;
        return memo[v];
    }
    public long maxScore(int[][] edges){
        int n=edges.length;
        ch=new ArrayList<>();
        for(int i=0;i<n;i++) ch.add(new ArrayList<>());
        for(int i=1;i<n;i++) ch.get(edges[i][0]).add(new long[]{i,edges[i][1]});
        memo=new long[n][3];
        return dfs(0)[0];
    }
}

