var maxScore = function(edges) {
    const n = edges.length;
    const ch = Array.from({length:n},()=>[]);
    for(let i=1;i<n;i++) ch[edges[i][0]].push([i, edges[i][1]]);
    function dfs(v){
        let s0=0, s1=0;
        for(const [c,w] of ch[v]){
            const [a,b]=dfs(c);
            s1+=a;
            s0+=Math.max(a, b+w);
        }
        return [s0,s1];
    }
    return dfs(0)[0];
